// Revelation chapter notes. Chapter 21 keeps its full notes in notes.js.
import { makeBook } from "./make.js";

const sources = {
  mounceR: "Robert H. Mounce, The Book of Revelation, rev. ed., New International Commentary on the New Testament (Eerdmans, 1998).",
  beale: "G. K. Beale, The Book of Revelation, New International Greek Testament Commentary (Eerdmans, 1999).",
  osborne: "Grant R. Osborne, Revelation, Baker Exegetical Commentary on the New Testament (Baker Academic, 2002).",
  keenerR: "Craig S. Keener, Revelation, NIV Application Commentary (Zondervan, 2000).",
  hemerR: "Colin J. Hemer, The Letters to the Seven Churches of Asia in Their Local Setting (Sheffield Academic Press, 1986).",
  thomasR: "Robert L. Thomas, Revelation 1-7 and Revelation 8-22, 2 vols., Wycliffe Exegetical Commentary (Moody, 1992-1995).",
  bdag: "Bauer, Danker, Arndt and Gingrich, A Greek-English Lexicon of the New Testament, 3rd ed. (University of Chicago Press, 2000).",
};

export default makeBook({ lang: "Greek", sources, use: ["mounceR", "osborne"] }, {
  1: {
    intro: "\"The Revelation of Jesus Christ, which God gave Him to show to His bond-servants.\" A blessing is promised to those who read, hear and keep it. John greets seven churches from the One \"who is and who was and who is to come.\" \"Behold, He is coming with the clouds, and every eye will see Him.\" \"I am the Alpha and the Omega.\" John, exiled on the island of Patmos for the word of God, was \"in the Spirit on the Lord's day\" and heard a voice like a trumpet. He turned and saw one like a son of man among seven golden lampstands, with eyes like fire, a voice like many waters, and a face shining like the sun. John fell at His feet, and Jesus said, \"Do not be afraid; I am the first and the last, and the living One; I was dead, and behold, I am alive forevermore, and I have the keys of death and of Hades.\"",
    v: [
      ["1:3", "Blessed is he who reads and those who hear the words of the prophecy", "The only book of the Bible that begins with a blessing for those who read it aloud and those who listen and keep it."],
      ["1:5", "To Him who loves us and released us from our sins by His blood", "Notice the order: He loves us now, and He has already freed us from our sins by His blood."],
      ["1:7", "Behold, He is coming with the clouds, and every eye will see Him", "Combining Daniel 7:13 and Zechariah 12:10. Jesus' return will not be secret; every eye will see Him."],
      ["1:8", "I am the Alpha and the Omega", "Alpha and Omega are the first and last letters of the Greek alphabet, like saying \"the A and the Z.\" God is before all things and after all things."],
      ["1:10", "I was in the Spirit on the Lord's day", "The Lord's day was the first day of the week, the day Jesus rose, when early Christians gathered to worship (Acts 20:7)."],
      ["1:17", "Do not be afraid; I am the first and the last", "John falls down as if dead, and Jesus touches him: do not be afraid. The same Jesus who is glorious is also gentle."],
      ["1:18", "I have the keys of death and of Hades", "Keys mean authority. Jesus died and lives forever, so death and the grave no longer have the last word."],
    ],
    bg: [["Patmos", "Patmos is a small rocky island in the Aegean Sea, about 40 miles off the coast of Turkey. Rome sometimes exiled troublemakers to islands. Most scholars date Revelation to about AD 95, under Emperor Domitian, when believers faced pressure to honor the emperor as a god.", "strong", ["mounceR", "osborne"]]],
    views: [["How to read Revelation", "Some readers see most of the book as future events just before Christ returns. Others see it as describing events in the first century, especially Rome's persecution. Others see it as a picture of the whole church age, with the same battle between Christ and evil shown again and again. Others see it as a mix. All agree on its main message: Jesus is Lord, evil will be defeated, and God's people should stay faithful.", ["osborne", "beale", "thomasR", "keenerR"]]],
    w: [["Revelation", "apokalypsis", "G602", "unveiling, revealing", "Pulling back a curtain to show what was hidden. The book reveals Jesus and what God is doing behind the scenes of history.", ["bdag"]]],
    refs: [["DAN.7", "Daniel 7:9-14", "The Ancient of Days and the Son of Man"], ["DAN.10", "Daniel 10:5-9", "A man with eyes like fire"], ["ZEC.12", "Zechariah 12:10", "They will look on Him whom they pierced"]],
  },
  2: {
    intro: "Jesus sends letters to four of the seven churches. To Ephesus: you work hard and test false teachers, but \"you have left your first love. Therefore remember from where you have fallen, and repent.\" To Smyrna, poor yet rich: \"Do not fear what you are about to suffer... Be faithful until death, and I will give you the crown of life.\" To Pergamum, \"where Satan's throne is\": you held fast, but some follow false teaching. To Thyatira: your love and service grow, but you tolerate \"Jezebel,\" who leads people into idolatry. To each comes a promise \"to him who overcomes\" and the call: \"He who has an ear, let him hear what the Spirit says to the churches.\"",
    v: [
      ["2:4", "You have left your first love", "The church in Ephesus worked hard and tested false teachers (2:2), but the love they had at first had faded. Jesus calls them to return to it (2:5)."],
      ["2:7", "To him who overcomes, I will grant to eat of the tree of life", "The tree of life was lost in Eden (Genesis 3:22-24). Jesus promises it back to those who overcome, in the paradise of God."],
      ["2:9", "I know your tribulation and your poverty (but you are rich)", "The believers in Smyrna were poor and persecuted, yet Jesus calls them rich. What they have in Him cannot be taken away."],
      ["2:10", "Be faithful until death, and I will give you the crown of life", "Smyrna would suffer for a short time. Jesus does not promise escape but life: stay faithful even to death, and receive the crown of life."],
      ["2:17", "I will give him a white stone, and a new name written on the stone", "In the ancient world a white stone could mean acquittal or an invitation to a feast. Jesus gives each overcomer a new name, known only to Him."],
      ["2:19", "Your deeds of late are greater than at first", "Thyatira's love, faith, service and endurance were growing. Their later works were greater than their first."],
    ],
    bg: [["Real cities, real problems", "The seven churches were real congregations on a postal route in western Turkey. Details in the letters fit each city: Smyrna was famous for loyalty to Rome, Pergamum had a great altar to Zeus and a center of emperor worship, and Thyatira had many trade guilds with pagan feasts.", "strong", ["hemerR", "osborne"]]],
    refs: [["ACT.19", "Acts 19", "The church at Ephesus begins"], ["GEN.2", "Genesis 2:9", "The tree of life"], ["NUM.25", "Numbers 25:1-3", "Balaam's trap"], ["1KI.16", "1 Kings 16:31", "Jezebel"]],
  },
  3: {
    intro: "To Sardis: \"you have a name that you are alive, but you are dead. Wake up.\" To Philadelphia, which has little power but kept His word: \"I have put before you an open door which no one can shut.\" \"I am coming quickly; hold fast what you have.\" To Laodicea: \"you are neither cold nor hot... because you are lukewarm... I will spit you out of My mouth.\" They say they are rich and need nothing, but they are poor, blind and naked. \"Those whom I love, I reprove and discipline.\" \"Behold, I stand at the door and knock; if anyone hears My voice and opens the door, I will come in to him and will dine with him, and he with Me.\"",
    v: [
      ["3:2", "Wake up, and strengthen the things that remain", "Sardis had a name for being alive but was dead (3:1). Jesus calls them to wake up and strengthen what little remains."],
      ["3:8", "I have put before you an open door which no one can shut", "Philadelphia had little strength, but it kept His word. Jesus has set an open door before them that no one can shut."],
      ["3:11", "Hold fast what you have, so that no one will take your crown", "Jesus is coming soon. Hold on to what you have, so no one robs you of your crown."],
      ["3:16", "Because you are lukewarm... I will spit you out of My mouth", "Nearby Hierapolis had hot springs, and Colossae had cold, fresh water. Laodicea's water arrived lukewarm. Their faith was neither healing nor refreshing."],
      ["3:19", "Those whom I love, I reprove and discipline", "Jesus' hard words come from love. He corrects those He loves, so be earnest and turn back."],
      ["3:20", "Behold, I stand at the door and knock", "Spoken to a church, not only to one person. Jesus stands at the door and knocks, wanting to come in and share a meal with anyone who opens."],
    ],
    bg: [["Lukewarm water", "Laodicea had no good water of its own and piped it in from springs miles away; it arrived lukewarm and full of minerals. Nearby Hierapolis had hot healing springs, and Colossae had cold, fresh water. Laodicea was also a banking center, made a famous eye salve, and produced black wool, which explains Jesus' words about riches, eye salve and white clothes.", "strong", ["hemerR", "keenerR"]]],
    refs: [["ISA.22", "Isaiah 22:22", "The key of David"], ["PRO.3", "Proverbs 3:12", "Whom the LORD loves He reproves"], ["COL.4", "Colossians 4:13-16", "Laodicea"]],
  },
  4: {
    intro: "John sees a door open in heaven and hears, \"Come up here.\" He sees a throne, and One sitting on it who looks like jasper and sardius stone, with a rainbow around the throne like an emerald. Around it are twenty-four elders in white with golden crowns, and from the throne come lightning and thunder. Four living creatures, like a lion, a calf, a man and a flying eagle, full of eyes, never stop saying, \"Holy, holy, holy is the Lord God, the Almighty, who was and who is and who is to come.\" The elders throw their crowns before the throne: \"Worthy are You, our Lord and our God, to receive glory and honor and power; for You created all things.\"",
    v: [
      ["4:1", "A door standing open in heaven", "After the seven letters, John is invited through an open door into heaven, to see things from God's throne."],
      ["4:2", "A throne was standing in heaven, and One sitting on the throne", "God is on the throne. Before any trouble on earth is shown, John sees God on His throne. Whatever happens next, He is still in charge."],
      ["4:3", "A rainbow around the throne, like an emerald in appearance", "God on His throne shines like precious stones, and an emerald-green rainbow circles the throne, recalling God's promise to Noah (Genesis 9:13)."],
      ["4:8", "Holy, holy, holy is the Lord God, the Almighty", "Like the seraphim in Isaiah 6:3, the four living creatures never stop calling God holy, holy, holy, the One who was, who is and who is to come."],
      ["4:10", "Will cast their crowns before the throne", "The twenty-four elders throw their crowns down before the throne. Every honor they have belongs to God."],
      ["4:11", "Worthy are You, our Lord and our God", "God is worthy of glory and honor because He created all things. Everything exists because He willed it."],
    ],
    refs: [["ISA.6", "Isaiah 6:1-3", "Holy, holy, holy"], ["EZK.1", "Ezekiel 1", "Four living creatures"], ["GEN.9", "Genesis 9:13", "The rainbow"]],
  },
  5: {
    intro: "In God's right hand is a scroll sealed with seven seals. An angel asks, \"Who is worthy to open the book?\" No one is found, and John weeps. Then an elder says, \"Stop weeping; behold, the Lion that is from the tribe of Judah, the Root of David, has overcome.\" John looks and sees a Lamb standing, as if slain. The Lamb takes the scroll, and the creatures and elders fall down with harps and golden bowls of incense, \"which are the prayers of the saints,\" and sing a new song: \"Worthy are You... for You were slain, and purchased for God with Your blood men from every tribe and tongue and people and nation.\" Then countless angels, and every creature in heaven and on earth, join the praise.",
    v: [
      ["5:2", "Who is worthy to open the book and to break its seals?", "The scroll holds God's plan for history. No one in heaven or on earth is found worthy to open it, and John weeps (5:4)."],
      ["5:5", "The Lion that is from the tribe of Judah... has overcome", "The elder speaks of a Lion from Judah (Genesis 49:9). John turns and sees a Lamb that looks as if it had been slain (5:6). Jesus conquers by the cross."],
      ["5:6", "A Lamb standing, as if slain", "The Lamb. John hears about a Lion and turns to see a Lamb. Jesus conquers by giving Himself, which is the heart of the whole book."],
      ["5:8", "Golden bowls full of incense, which are the prayers of the saints", "The prayers of God's people rise before Him like incense in golden bowls. Not one is forgotten."],
      ["5:9", "From every tribe and tongue and people and nation", "A new song for the Lamb: by His blood He bought people for God from every tribe, language, people and nation."],
      ["5:12", "Worthy is the Lamb that was slain", "Thousands upon thousands of angels sing with a loud voice that the slain Lamb is worthy of power, riches, wisdom, strength, honor, glory and praise."],
    ],
    refs: [["GEN.49", "Genesis 49:9-10", "The lion of Judah"], ["ISA.53", "Isaiah 53:7", "Like a lamb led to slaughter"], ["JHN.1", "John 1:29", "Behold, the Lamb of God"], ["PSA.141", "Psalm 141:2", "Prayer like incense"]],
  },
  6: {
    intro: "The Lamb opens the first six seals. Four riders go out on horses: white (conquest), red (war), black (famine, with a day's wages for a little wheat), and pale (death). At the fifth seal, the souls of those killed for God's word cry out, \"How long, O Lord?\" They are given white robes and told to rest a little longer. At the sixth seal there is a great earthquake, the sun turns black, the stars fall, and the sky splits like a scroll. Kings and everyone else hide in caves and call to the mountains, \"Fall on us and hide us from the presence of Him who sits on the throne, and from the wrath of the Lamb... and who is able to stand?\"",
    v: [
      ["6:2", "He went out conquering and to conquer", "The first rider, with a bow and a crown, goes out to conquer. Some see conquest and war; others see the spread of the gospel. Readers differ."],
      ["6:8", "A pale horse; and he who sat on it had the name Death", "The fourth horse is a sickly pale green, ridden by Death, with the grave following. Even it is limited, to a fourth of the earth."],
      ["6:10", "How long, O Lord, holy and true?", "The souls of those killed for God's word cry out for justice. They trust God to make things right."],
      ["6:11", "There was given to each of them a white robe", "Each martyr is given a white robe and told to rest a little longer. God has not forgotten them."],
      ["6:16", "Hide us from the presence of Him who sits on the throne", "When the sixth seal is opened, people of every rank try to hide from the face of God and the anger of the Lamb."],
      ["6:17", "Who is able to stand?", "The question hangs in the air: who can stand on that day? Chapter 7 shows God's sealed people standing before His throne."],
    ],
    refs: [["ZEC.6", "Zechariah 6:1-8", "Four chariots and horses"], ["MAT.24", "Matthew 24:6-8", "Wars, famines, earthquakes"], ["PSA.13", "Psalm 13:1", "How long, O LORD?"], ["HOS.10", "Hosea 10:8", "Mountains, cover us"]],
  },
  7: {
    intro: "Before more judgment, four angels hold back the winds while God's servants are sealed on their foreheads: 144,000, twelve thousand from each tribe of Israel. Then John looks and sees \"a great multitude which no one could count, from every nation and all tribes and peoples and tongues, standing before the throne and before the Lamb, clothed in white robes, and palm branches were in their hands.\" They cry, \"Salvation to our God who sits on the throne, and to the Lamb.\" These have come out of the great tribulation and washed their robes in the blood of the Lamb. \"They will hunger no longer, nor thirst anymore... for the Lamb... will be their shepherd, and will guide them to springs of the water of life; and God will wipe every tear from their eyes.\"",
    v: [
      ["7:3", "Until we have sealed the bond-servants of our God on their foreheads", "Before judgment falls, God marks His servants on their foreheads, as in Ezekiel 9:4. They belong to Him and are kept."],
      ["7:9", "A great multitude which no one could count, from every nation", "John hears 144,000 from Israel's tribes (7:4), then turns and sees a crowd no one could count, from every nation, in white robes before the Lamb."],
      ["7:10", "Salvation to our God who sits on the throne, and to the Lamb", "The great crowd cries out that salvation belongs to God and to the Lamb. No one saves themselves."],
      ["7:14", "They have washed their robes and made them white in the blood of the Lamb", "These came through great suffering. Robes washed white in blood is a picture: Jesus' sacrifice makes them clean."],
      ["7:17", "The Lamb... will be their shepherd... and God will wipe every tear from their eyes", "The Lamb becomes their Shepherd, leading them to springs of living water, and God wipes away every tear (Isaiah 25:8)."],
    ],
    views: [["Who are the 144,000?", "Some read them as Jewish believers in the end times, an actual number from each tribe. Others read them as the whole people of God, Jewish and Gentile, pictured as the complete Israel (12 x 12 x 1,000), and see the countless multitude as the same group seen from another angle, just as John heard of a Lion and saw a Lamb. Others see them as a special group of faithful witnesses. All agree that God knows and protects His own.", ["beale", "thomasR", "osborne"]]],
    refs: [["EZK.9", "Ezekiel 9:4", "A mark on the foreheads"], ["ISA.25", "Isaiah 25:8", "He will wipe tears away"], ["PSA.23", "Psalm 23", "The LORD is my shepherd"], ["GEN.15", "Genesis 15:5", "Count the stars"]],
  },
  8: {
    intro: "When the Lamb opens the seventh seal, there is silence in heaven for about half an hour. Seven angels are given seven trumpets. Another angel offers incense with the prayers of all the saints on the golden altar, and the smoke of the incense rises before God; then he throws fire on the earth. The first four trumpets bring hail and fire, a burning mountain thrown into the sea, a star named Wormwood that makes waters bitter, and darkness over a third of the sun, moon and stars. An eagle flies overhead crying, \"Woe, woe, woe\" for the three trumpets still to come.",
    v: [
      ["8:1", "There was silence in heaven for about half an hour", "After all the loud worship, the seventh seal brings silence in heaven for about half an hour, a hush before God acts."],
      ["8:3", "Much incense was given to him... with the prayers of all the saints", "An angel offers incense with the prayers of all God's people on the golden altar before the throne."],
      ["8:4", "The smoke of the incense, with the prayers of the saints, went up before God", "The smoke rises before God with the prayers. What follows on earth is part of God's answer to His people's cries (6:10)."],
      ["8:7", "Hail and fire, mixed with blood", "Hail and fire recall the seventh plague on Egypt (Exodus 9:23-25). God judges as He did when He freed His people."],
      ["8:11", "The name of the star is called Wormwood", "Wormwood is a bitter plant. In the Old Testament it is a picture of the bitterness that follows unfaithfulness (Jeremiah 9:15)."],
      ["8:13", "Woe, woe, woe to those who dwell on the earth", "An eagle flying overhead cries three woes. The last three trumpets will be even harder."],
    ],
    bg: [["Echoes of the Exodus", "The trumpet judgments echo the plagues on Egypt: hail and fire, water turned to blood, darkness, locusts. As in the Exodus, they are warnings meant to lead people to repent, and only a part (a third) is struck.", "strong", ["beale", "keenerR"]]],
    refs: [["EXO.9", "Exodus 9:23-25", "Hail and fire"], ["EXO.7", "Exodus 7:20-21", "Water to blood"], ["JOS.6", "Joshua 6", "Trumpets at Jericho"], ["PSA.141", "Psalm 141:2", "Prayer as incense"]],
  },
  9: {
    intro: "At the fifth trumpet a star falls with the key to the bottomless pit. Smoke pours out, and from it come locusts with power like scorpions, told not to harm those with God's seal, only to torment others for five months. They have a king, the angel of the abyss, called Abaddon in Hebrew and Apollyon in Greek, both meaning \"Destroyer.\" At the sixth trumpet four angels bound at the Euphrates are released, with an army of two hundred million horsemen, and a third of mankind is killed. Yet the rest still \"did not repent of the works of their hands,\" their idols, murders, sorceries, immorality and thefts.",
    v: [
      ["9:1", "The key of the bottomless pit was given to him", "The key \"was given\": even the forces of the abyss can act only as far as God allows."],
      ["9:4", "Only the men who do not have the seal of God on their foreheads", "The locusts may not harm those sealed by God (7:3). His people are marked as His and kept."],
      ["9:6", "Men will seek death and will not find it", "The suffering is so great that people long to die. Revelation shows how miserable life becomes when people refuse God."],
      ["9:11", "His name in Hebrew is Abaddon, and in the Greek he has the name Apollyon", "Both names mean Destroyer. Evil's king destroys; Jesus, the true King, gives life."],
      ["9:16", "The number of the armies of the horsemen was two hundred million", "Literally \"twice ten thousand times ten thousand,\" an overwhelming number. Readers differ on whether it is meant literally or as a picture of vast forces."],
      ["9:20", "The rest of mankind... did not repent", "Even after terrible judgments, people kept worshiping idols and did not turn from murder, sorcery, immorality and theft (9:21)."],
    ],
    refs: [["JOL.2", "Joel 2:1-11", "A locust army"], ["EXO.10", "Exodus 10:12-15", "Locusts in Egypt"], ["EXO.8", "Exodus 8:15", "Pharaoh hardened his heart"]],
  },
  10: {
    intro: "A strong angel comes down from heaven, wrapped in a cloud, with a rainbow on his head, a face like the sun and feet like pillars of fire. He holds a little open scroll, sets one foot on the sea and one on the land, and shouts like a lion; seven peals of thunder speak. John is about to write, but is told, \"Seal up the things which the seven peals of thunder have spoken.\" The angel swears there will be no more delay: at the seventh trumpet, the mystery of God will be finished. John is told to take and eat the little scroll: \"it will make your stomach bitter, but in your mouth it will be sweet as honey.\" Then: \"You must prophesy again.\"",
    v: [
      ["10:1", "A rainbow was upon his head, and his face was like the sun", "The rainbow recalls God's promise to Noah (Genesis 9:13). Even in judgment, God remembers mercy."],
      ["10:2", "He placed his right foot on the sea and his left on the land", "Standing on sea and land at once, the angel's message concerns the whole earth."],
      ["10:4", "Seal up the things which the seven peals of thunder have spoken", "John is told not to write down what the thunders said. God has not revealed everything, and some things are His alone (Deuteronomy 29:29)."],
      ["10:6", "There will be delay no longer", "No more waiting: when the seventh trumpet sounds, God's hidden plan, announced by the prophets, will be finished (10:7)."],
      ["10:9", "It will make your stomach bitter, but in your mouth it will be sweet as honey", "Like Ezekiel (Ezekiel 3:1-3), John eats a scroll. God's word is sweet to receive, but announcing judgment can be bitter."],
      ["10:11", "You must prophesy again", "John's work is not over. He must keep speaking God's word about many peoples, nations and kings."],
    ],
    refs: [["EZK.3", "Ezekiel 3:1-3", "Ezekiel eats the scroll"], ["DAN.12", "Daniel 12:4-9", "Seal up the book"], ["PSA.119", "Psalm 119:103", "Sweeter than honey"]],
  },
  11: {
    intro: "John measures the temple of God, but the outer court is given to the nations, who will trample the holy city for forty-two months. God's two witnesses prophesy for 1,260 days, dressed in sackcloth. They are \"the two olive trees and the two lampstands\" and have power like Moses and Elijah. When they finish, the beast kills them, and people celebrate over their bodies. But after three and a half days, the breath of life from God enters them, and they stand up and go up to heaven in a cloud. At the seventh trumpet, loud voices in heaven say, \"The kingdom of the world has become the kingdom of our Lord and of His Christ; and He will reign forever and ever.\"",
    v: [
      ["11:3", "I will grant authority to my two witnesses", "God gives His two witnesses power to prophesy for 1,260 days, dressed in sackcloth. Readers differ on whether they are two people or a picture of the witnessing church."],
      ["11:4", "These are the two olive trees and the two lampstands", "The two olive trees and lampstands come from Zechariah 4, where they stood for God's anointed leaders, kept burning by His Spirit."],
      ["11:11", "The breath of life from God came into them, and they stood on their feet", "The witnesses lie dead in the street for three and a half days, then God breathes life into them and they stand up, as in Ezekiel 37:10."],
      ["11:15", "The kingdom of the world has become the kingdom of our Lord and of His Christ", "The seventh trumpet sounds, and heaven announces that the kingdom of the world now belongs to our Lord and His Christ, and He will reign forever."],
      ["11:17", "We give You thanks, O Lord God, the Almighty", "The elders thank God that He has taken His great power and begun to reign."],
      ["11:19", "The ark of His covenant appeared in His temple", "God's temple in heaven opens and the ark of His covenant is seen. The ark, lost on earth, stood for God's presence with His people."],
    ],
    views: [["Who are the two witnesses?", "Some read them as two individual prophets in the end times, perhaps Moses and Elijah or men like them. Others read them as a picture of the witnessing church, since the lampstands stand for churches in chapter 1 and two witnesses were needed for valid testimony. All agree that God protects His witnesses until their work is done and that death cannot hold them.", ["beale", "thomasR", "mounceR"]]],
    refs: [["ZEC.4", "Zechariah 4:1-14", "Two olive trees"], ["1KI.17", "1 Kings 17:1", "Elijah shuts the sky"], ["EZK.37", "Ezekiel 37:10", "Breath enters them"], ["DAN.7", "Daniel 7:14", "An everlasting kingdom"]],
  },
  12: {
    intro: "A great sign appears in heaven: a woman clothed with the sun, with the moon under her feet and a crown of twelve stars, about to give birth. A great red dragon with seven heads and ten horns waits to devour her child. She gives birth to a son \"who is to rule all the nations with a rod of iron,\" and her child is caught up to God and His throne. The woman flees to the wilderness, where God cares for her. War breaks out in heaven: Michael and his angels fight the dragon, \"the serpent of old who is called the devil and Satan,\" and throw him down. A loud voice says, \"They overcame him because of the blood of the Lamb and because of the word of their testimony.\" The angry dragon goes off to make war with the rest of her children.",
    v: [
      ["12:1", "A woman clothed with the sun", "John sees a woman clothed with the sun, the moon under her feet and twelve stars on her head. Many see Israel, from whom the Messiah came; readers also see Mary or the church."],
      ["12:5", "She gave birth to a son, a male child, who is to rule all the nations", "Her son is to rule the nations with a rod of iron, words from Psalm 2:9 about the Messiah. He is caught up to God's throne."],
      ["12:7", "Michael and his angels waging war with the dragon", "Michael the archangel (Daniel 10:13; Jude 9) and his angels fight the dragon, and the dragon loses his place in heaven."],
      ["12:9", "The serpent of old who is called the devil and Satan", "The dragon is named: the ancient serpent of Eden, the devil and Satan, who deceives the whole world."],
      ["12:11", "They overcame him because of the blood of the Lamb and because of the word of their testimony", "Believers defeat Satan not by their own strength, but by the blood of the Lamb, by telling the truth about Jesus, and by not loving their lives more than Him."],
      ["12:12", "Knowing that he has only a short time", "Heaven rejoices, but the devil comes down in fury, because he knows his time is short."],
    ],
    bg: [["Signs in the sky", "John's readers knew stories of a dragon attacking a goddess and her newborn, and Rome used such myths to praise the emperor. John's vision retells the real story: the true King is Jesus, and the dragon has already lost.", "debated", ["keenerR", "osborne"]]],
    refs: [["GEN.3", "Genesis 3:15", "The serpent and the woman's offspring"], ["PSA.2", "Psalm 2:9", "Rule with a rod of iron"], ["DAN.12", "Daniel 12:1", "Michael the great prince"], ["LUK.10", "Luke 10:18", "Satan falls like lightning"]],
  },
  13: {
    intro: "John sees a beast rising from the sea with ten horns and seven heads, like a leopard, a bear and a lion together. The dragon gives it power, and one of its heads seems to have a fatal wound that is healed. The whole earth follows the beast and worships the dragon: \"Who is like the beast, and who is able to wage war with him?\" It speaks against God and makes war on the saints. Then a second beast rises from the earth, with two horns like a lamb but speaking like a dragon. It performs signs and makes everyone receive a mark on the right hand or forehead, so that no one can buy or sell without it. \"Here is wisdom... the number of the beast... is that of a man; and his number is six hundred and sixty-six.\"",
    v: [
      ["13:1", "A beast coming up out of the sea, having ten horns and seven heads", "The beast from the sea has ten horns and seven heads, a mix of the four beasts in Daniel 7. It pictures proud human power set against God."],
      ["13:4", "Who is like the beast, and who is able to wage war with him?", "People worship the dragon and the beast and say no one can fight it. Their words copy praise that belongs to God alone (Exodus 15:11)."],
      ["13:8", "The book of life of the Lamb who has been slain", "Those who worship the beast are those whose names are not written in the Lamb's book of life. God knows His own."],
      ["13:10", "Here is the perseverance and the faith of the saints", "Believers are not told to fight back with the sword. The call is to patient endurance and faithfulness."],
      ["13:11", "He had two horns like a lamb and he spoke as a dragon", "The second beast looks like a lamb but speaks like a dragon. Evil often looks harmless while it leads people to false worship."],
      ["13:18", "His number is six hundred and sixty-six", "John calls for wisdom. Many note that the Hebrew letters of \"Nero Caesar\" add up to 666; others see 6 falling short of 7, the number of completeness. Readers differ."],
    ],
    views: [["What does 666 mean?", "Some see a code for a first-century ruler: the letters of \"Nero Caesar\" in Hebrew add up to 666. Others expect a future world ruler whose name will fit the number. Others see it as a symbol: six falls short of seven, the number of completeness, so 666 is humanity trying to be God and failing. All agree believers should refuse to give their worship and loyalty to anyone but God.", ["mounceR", "beale", "thomasR"]]],
    refs: [["DAN.7", "Daniel 7:2-8", "Four beasts from the sea"], ["DAN.3", "Daniel 3", "Worship the image or else"], ["2TH.2", "2 Thessalonians 2:3-10", "The man of lawlessness"]],
  },
  14: {
    intro: "The Lamb stands on Mount Zion with the 144,000, who have His name and His Father's name on their foreheads, and they sing a new song. Three angels fly through the sky: the first proclaims \"an eternal gospel\" to every nation, \"Fear God, and give Him glory... worship Him who made the heaven and the earth\"; the second announces, \"Fallen, fallen is Babylon the great\"; the third warns against worshiping the beast. \"Here is the perseverance of the saints who keep the commandments of God and their faith in Jesus.\" A voice says, \"Blessed are the dead who die in the Lord from now on... they may rest from their labors.\" Then one like a son of man reaps the earth with a sharp sickle, and the winepress of God's wrath is trodden.",
    v: [
      ["14:1", "The Lamb was standing on Mount Zion", "In contrast to the beast's followers marked on their foreheads (13:16), the Lamb's people bear His and His Father's name."],
      ["14:4", "These are the ones who follow the Lamb wherever He goes", "The mark of these believers is simple: they follow the Lamb wherever He leads."],
      ["14:6", "Having an eternal gospel to preach to those who live on the earth", "Before the end, the good news goes out to every nation, tribe, language and people."],
      ["14:7", "Worship Him who made the heaven and the earth", "The call is to fear God and worship the Creator of heaven, earth, sea and springs of water."],
      ["14:12", "Here is the perseverance of the saints", "When the pressure is to worship the beast, God's people keep His commandments and their faith in Jesus."],
      ["14:13", "Blessed are the dead who die in the Lord", "For those who die belonging to the Lord, death is rest from their labors, and their good deeds follow them."],
    ],
    refs: [["PSA.2", "Psalm 2:6", "My King on Zion"], ["JOL.3", "Joel 3:13", "Put in the sickle"], ["ISA.21", "Isaiah 21:9", "Fallen is Babylon"], ["MAT.13", "Matthew 13:30-43", "The harvest at the end"]],
  },
  15: {
    intro: "John sees seven angels with the seven last plagues, which complete God's wrath. He also sees something like a sea of glass mixed with fire, and standing on it are those who overcame the beast, holding harps of God. \"They sang the song of Moses, the bond-servant of God, and the song of the Lamb, saying, 'Great and marvelous are Your works, O Lord God, the Almighty; righteous and true are Your ways, King of the nations! Who will not fear, O Lord, and glorify Your name? For You alone are holy; for all the nations will come and worship before You.'\" The temple fills with smoke from God's glory, and no one can enter until the plagues are finished.",
    v: [
      ["15:2", "Standing on the sea of glass, holding harps of God", "Those who overcame the beast stand beside a sea of glass, holding harps, like Israel standing safe beyond the Red Sea."],
      ["15:3", "The song of Moses... and the song of the Lamb... Great and marvelous are Your works", "Songs of rescue. Like Israel singing on the far side of the Red Sea, God's people sing after He brings them safely through."],
      ["15:4", "All the nations will come and worship before You", "They sing the song of Moses and the Lamb (15:3): all nations will come and worship, because God's righteous acts have been revealed."],
      ["15:8", "The temple was filled with smoke from the glory of God", "The temple fills with the smoke of God's glory, as the tabernacle and temple once did (Exodus 40:34-35; 1 Kings 8:10-11)."],
    ],
    refs: [["EXO.15", "Exodus 15:1-18", "The song of Moses"], ["PSA.86", "Psalm 86:9", "All nations will worship"], ["EXO.40", "Exodus 40:34-35", "Glory fills the tabernacle"]],
  },
  16: {
    intro: "A loud voice tells the seven angels to pour out the seven bowls of God's wrath. Sores break out on those with the mark of the beast; the sea and rivers become blood; the sun scorches people with fire; darkness falls on the beast's kingdom; the Euphrates dries up, and evil spirits like frogs gather the kings of the earth for war \"at the place which in Hebrew is called Har-Magedon.\" Jesus says, \"Behold, I am coming like a thief. Blessed is the one who stays awake.\" At the seventh bowl a loud voice from the throne says, \"It is done,\" and the greatest earthquake ever splits the great city. Yet people still blaspheme God and do not repent.",
    v: [
      ["16:5", "Righteous are You, who are and who were, O Holy One", "The angel over the waters declares God righteous in His judgments. Those who shed His people's blood are given blood to drink (16:6)."],
      ["16:7", "True and righteous are Your judgments", "A voice from the altar agrees: God's judgments are true and just. He is never unfair."],
      ["16:9", "They did not repent so as to give Him glory", "Scorched by terrible heat, people curse God's name but do not turn back to Him."],
      ["16:15", "Behold, I am coming like a thief. Blessed is the one who stays awake", "In the middle of the bowls Jesus speaks: I am coming like a thief. Blessed is the one who stays awake and ready."],
      ["16:16", "The place which in Hebrew is called Har-Magedon", "Har-Magedon may mean \"mountain of Megiddo.\" Megiddo was the site of many famous battles in Israel's history (Judges 5:19; 2 Kings 23:29)."],
      ["16:17", "It is done", "When the seventh bowl is poured out, a loud voice from the throne says, It is done. God's judgment is complete."],
    ],
    bg: [["Megiddo", "Har-Magedon likely means \"mountain of Megiddo.\" Megiddo guarded a key pass into the Jezreel Valley in northern Israel, where many famous battles were fought (Judges 5:19; 2 Kings 23:29). It became a symbol of the final battle.", "strong", ["mounceR", "osborne"]]],
    refs: [["EXO.9", "Exodus 9:8-11", "Boils"], ["EXO.10", "Exodus 10:21-23", "Darkness"], ["JDG.5", "Judges 5:19", "Kings fought at Megiddo"], ["MAT.24", "Matthew 24:43-44", "Like a thief"]],
  },
  17: {
    intro: "An angel shows John \"the great harlot,\" a woman dressed in purple and scarlet, glittering with gold and pearls, sitting on a scarlet beast with seven heads and ten horns. On her forehead is written, \"Babylon the great, the mother of harlots.\" She is drunk with the blood of the saints. The angel explains: the seven heads are seven mountains on which she sits, and also seven kings; the ten horns are ten kings who give their power to the beast. \"These will wage war against the Lamb, and the Lamb will overcome them, because He is Lord of lords and King of kings, and those who are with Him are the called and chosen and faithful.\" In the end the beast and the kings turn on the harlot and destroy her.",
    v: [
      ["17:4", "The woman was clothed in purple and scarlet", "The woman is dressed in purple and scarlet and covered in gold and jewels. She pictures a world system that seduces with wealth."],
      ["17:5", "Babylon the great, the mother of harlots", "Babylon was Israel's great enemy that destroyed Jerusalem. Here the name stands for proud human power that opposes God (1 Peter 5:13)."],
      ["17:6", "Drunk with the blood of the saints", "The woman is drunk with the blood of God's people and of the witnesses to Jesus. She persecutes believers."],
      ["17:9", "The seven heads are seven mountains on which the woman sits", "Rome was famous as the city on seven hills, so many readers saw Rome here. The picture also fits every proud power like it."],
      ["17:14", "The Lamb will overcome them, because He is Lord of lords and King of kings", "The kings will make war on the Lamb, but He will defeat them, because He is Lord of lords and King of kings, and His called and faithful ones are with Him."],
      ["17:17", "God has put it in their hearts to execute His purpose", "Even the plans of evil rulers end up serving God's purpose. He remains in control until His words are fulfilled."],
    ],
    bg: [["The city on seven hills", "Rome was famous as the city built on seven hills, and its coins pictured the goddess Roma seated on them. Many scholars believe John's first readers would have recognized Rome in \"Babylon,\" just as Peter calls Rome \"Babylon\" (1 Peter 5:13). Others see Babylon as any proud, God-defying world system, or a future city.", "debated", ["mounceR", "keenerR", "thomasR"]]],
    refs: [["JER.51", "Jeremiah 51:6-13", "Babylon on many waters"], ["DAN.7", "Daniel 7:24", "Ten horns are ten kings"], ["1PE.5", "1 Peter 5:13", "She who is in Babylon"]],
  },
  18: {
    intro: "An angel with great authority lights up the earth and cries, \"Fallen, fallen is Babylon the great!\" Another voice calls, \"Come out of her, my people, so that you will not participate in her sins.\" In one hour her judgment comes. Kings who lived in luxury with her weep, merchants mourn because no one buys their cargoes anymore (gold, silver, jewels, fine linen, spices, horses, chariots, \"and slaves and human lives\"), and sailors stand far off crying, \"What city is like the great city?\" A strong angel throws a great millstone into the sea: \"So will Babylon... be thrown down with violence, and will not be found any longer.\" No more music, no more craftsmen, no more lamps or wedding songs.",
    v: [
      ["18:2", "Fallen, fallen is Babylon the great!", "Echoing Isaiah 21:9. \"Babylon\" stands for proud human power that sets itself against God. It looks unshakable, but it falls."],
      ["18:4", "Come out of her, my people", "God calls His people to come out of Babylon's ways, as He once called Israel out of the real Babylon (Jeremiah 51:45)."],
      ["18:7", "I sit as a queen and I am not a widow, and will never see mourning", "Babylon boasts she will never grieve. Pride that thinks it is safe from loss is close to a fall."],
      ["18:10", "In one hour your judgment has come", "Kings, merchants and sailors watch from far away as the city's wealth disappears in a single hour."],
      ["18:13", "Slaves and human lives", "The long cargo list ends with \"slaves and human lives.\" A system that treats people as merchandise is under God's judgment."],
      ["18:21", "A strong angel took up a stone like a great millstone and threw it into the sea", "A millstone thrown into the sea sinks and never comes back up. So will Babylon disappear."],
    ],
    refs: [["JER.51", "Jeremiah 51:45, 63-64", "Come out; the sinking scroll"], ["ISA.47", "Isaiah 47:7-9", "I will not sit as a widow"], ["EZK.27", "Ezekiel 27", "The lament over Tyre"]],
  },
  19: {
    intro: "A great multitude in heaven shouts, \"Hallelujah! Salvation and glory and power belong to our God; because His judgments are true and righteous.\" \"Hallelujah! For the Lord our God, the Almighty, reigns. Let us rejoice and be glad and give the glory to Him, for the marriage of the Lamb has come and His bride has made herself ready.\" \"Blessed are those who are invited to the marriage supper of the Lamb.\" John falls to worship the angel, but is told, \"Do not do that... worship God.\" Then heaven opens: a white horse, and its Rider is called Faithful and True, His eyes like fire, many crowns on His head, His robe dipped in blood, \"and His name is called The Word of God.\" On His robe is written, \"KING OF KINGS, AND LORD OF LORDS.\" The beast and false prophet are captured and thrown into the lake of fire.",
    v: [
      ["19:1", "Hallelujah! Salvation and glory and power belong to our God", "\"Hallelujah\" means \"Praise the LORD.\" These verses are the only place in the New Testament where the word appears, four times in a row (19:1, 3, 4, 6)."],
      ["19:6", "Hallelujah! For the Lord our God, the Almighty, reigns", "The sound of a huge crowd, like rushing water and loud thunder, celebrating that God reigns."],
      ["19:7", "The marriage of the Lamb has come and His bride has made herself ready", "The church is pictured as a bride, and Jesus as the Bridegroom. History is heading toward a wedding."],
      ["19:9", "Blessed are those who are invited to the marriage supper of the Lamb", "Jesus told parables about wedding feasts (Matthew 22:1-14). Being invited to this one is pure blessing."],
      ["19:10", "Worship God", "John falls at the angel's feet, and the angel stops him. Only God is to be worshiped."],
      ["19:11", "He who sat on it is called Faithful and True", "Riding a white horse, Jesus comes as a warrior-king who judges and fights with justice."],
      ["19:16", "KING OF KINGS, AND LORD OF LORDS", "Written on His robe and thigh, the title says no ruler anywhere is above Him."],
    ],
    w: [["Hallelujah", "allēlouia", "G239", "Praise the LORD!", "A Hebrew word, hallelu-Yah, \"Praise Yah (the LORD).\" It appears in the New Testament only here, four times in this chapter, as heaven celebrates.", ["bdag", "mounceR"]]],
    refs: [["PSA.146", "Psalms 146-150", "Hallelujah psalms"], ["ISA.63", "Isaiah 63:1-6", "Garments stained red"], ["JHN.1", "John 1:1", "The Word"], ["MAT.22", "Matthew 22:1-14", "The wedding feast"]],
  },
  20: {
    intro: "An angel comes down with the key of the abyss and a great chain, binds the dragon, \"the serpent of old, who is the devil and Satan,\" for a thousand years, and seals him in the abyss so he can no longer deceive the nations. John sees thrones, and the souls of those who had been faithful to Jesus, who come to life and reign with Christ for a thousand years. \"Blessed and holy is the one who has a part in the first resurrection.\" Afterward Satan is released, gathers the nations for battle, and is defeated by fire from heaven and thrown into the lake of fire forever. Then John sees a great white throne. The dead, great and small, stand before it, and the books are opened, including the book of life. Death and Hades are thrown into the lake of fire.",
    v: [
      ["20:2", "He laid hold of the dragon... and bound him for a thousand years", "Christians read the thousand years in different ways (see the views below). All agree that Satan's power is limited, and that God is in control."],
      ["20:4", "They came to life and reigned with Christ for a thousand years", "Those who were faithful, even to death, share in Christ's reign. Their faithfulness was not wasted."],
      ["20:6", "Blessed and holy is the one who has a part in the first resurrection", "The \"second death\" (the lake of fire, 20:14) has no power over those who belong to Christ."],
      ["20:10", "The devil who deceived them was thrown into the lake of fire", "Satan's final end. The deceiver who has troubled the world since the garden is defeated forever."],
      ["20:11", "I saw a great white throne and Him who sat upon it", "Earth and heaven flee from the presence of the One on the throne. Every person will stand before God."],
      ["20:12", "The dead, the great and the small, standing before the throne", "Great and small alike are judged. No one is too important or too unimportant to answer to God, and the book of life is opened."],
      ["20:14", "Death and Hades were thrown into the lake of fire", "Paul called death \"the last enemy\" (1 Corinthians 15:26). Here death itself is destroyed."],
    ],
    views: [["The thousand years", "Some believers expect Christ to return first and then reign on earth for a literal thousand years before the final judgment. Others read the thousand years as the present church age, in which Satan is limited by the gospel and believers reign with Christ, ending with His one return. Others expect the gospel to spread until the world is largely changed, after which Christ returns. All agree that Christ will return, Satan will be defeated forever, the dead will be raised, and God will judge with justice.", ["osborne", "beale", "thomasR", "mounceR"]]],
    refs: [["DAN.7", "Daniel 7:9-10, 22", "Thrones and books opened"], ["EZK.38", "Ezekiel 38-39", "Gog and Magog"], ["1CO.15", "1 Corinthians 15:24-26", "The last enemy is death"], ["MAT.25", "Matthew 25:31-46", "The judgment of the nations"]],
  },
  22: {
    intro: "The angel shows John \"a river of the water of life, clear as crystal, coming from the throne of God and of the Lamb.\" On each side of the river is the tree of life, bearing twelve kinds of fruit every month, \"and the leaves of the tree were for the healing of the nations.\" There will no longer be any curse. \"They will see His face, and His name will be on their foreheads.\" No night, no lamps, \"because the Lord God will illumine them.\" Jesus says, \"Behold, I am coming quickly.\" \"I am the Alpha and the Omega, the first and the last, the beginning and the end.\" \"The Spirit and the bride say, 'Come.' And let the one who is thirsty come; let the one who wishes take the water of life without cost.\" \"Yes, I am coming quickly.\" \"Amen. Come, Lord Jesus.\"",
    v: [
      ["22:1", "A river of the water of life, clear as crystal", "The river of life. The Bible ends where it began: a garden, a river and the tree of life, but now with God living among His people forever and the curse gone. Families can read Genesis 2-3 and Revelation 22 side by side."],
      ["22:2", "The leaves of the tree were for the healing of the nations", "The tree of life, lost in Eden (Genesis 3:22-24), stands again by the river, and its leaves bring healing to every nation."],
      ["22:3", "There will no longer be any curse", "The curse that came with the first sin (Genesis 3:17) is gone for good. The Bible's story ends where it began, but better."],
      ["22:4", "They will see His face", "Moses could not see God's face and live (Exodus 33:20). In the new creation, God's servants will see Him face to face."],
      ["22:13", "I am the Alpha and the Omega, the first and the last", "Jesus takes the title God uses of Himself (Isaiah 44:6; Revelation 1:8). He is there at the beginning and the end of everything."],
      ["22:17", "Let the one who is thirsty come; let the one who wishes take the water of life without cost", "The Spirit and the church say \"Come.\" The water of life is free for anyone who is thirsty (Isaiah 55:1)."],
      ["22:20", "Amen. Come, Lord Jesus", "The Bible's last prayer is short: \"Come, Lord Jesus.\" Early Christians prayed it in Aramaic as Maranatha (1 Corinthians 16:22)."],
    ],
    refs: [["GEN.2", "Genesis 2:8-10", "A river and the tree of life"], ["GEN.3", "Genesis 3:17-24", "The curse and the closed garden"], ["EZK.47", "Ezekiel 47:1-12", "The river from the temple"], ["ISA.55", "Isaiah 55:1", "Come, buy without money"], ["1CO.16", "1 Corinthians 16:22", "Maranatha"]],
  },
});
